def solve(values):
    if len(values) < 2:
        return 0  # Not a valid window
    max_sum = sum(values[0:2])
    start_index = 0
    for i in range(1, len(values) - 1):
        current_sum = values[i] + values[i+1]
        if current_sum > max_sum:
            max_sum = current_sum
            start_index = i
    return start_index
